16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
23	    @Mapping(target = "initials", expression = "java(initials(owner))")
24	    @Mapping(target = "membershipTier", expression = "java(membershipTier(owner))")
25	    @Mapping(target = "locality", expression = "java(locality(owner))")
26	    @Mapping(target = "bulkSignupWarning", ignore = true)
27	    OwnerDto toOwnerDto(Owner owner);
28	
29	    /** Fixed city-to-region table used to derive an owner's locality at read time. */
30	    Map<String, String> CITY_REGION = Map.of(
31	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
32	
33	    /**
34	     * The owner's locality, derived at read time from the city via the fixed
35	     * {@link #CITY_REGION} table, or {@code UNKNOWN} when the city is not in the table.
36	     */
37	    default String locality(Owner owner) {
38	        if (owner == null) {
39	            return null;
40	        }
41	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
42	    }
43	
44	    /**
45	     * The owner's membership tier, derived at read time: {@code SILVER} when the owner's
46	     * namesakeCount is 0 and an email is present, otherwise {@code BRONZE}.
47	     */
48	    default OwnerDto.MembershipTierEnum membershipTier(Owner owner) {
49	        if (owner == null) {
50	            return null;
51	        }
52	        Integer namesakeCount = owner.getNamesakeCount();
53	        String email = owner.getEmail();
54	        boolean silver = namesakeCount != null && namesakeCount == 0
55	            && email != null && !email.isEmpty();
56	        return silver ? OwnerDto.MembershipTierEnum.SILVER : OwnerDto.MembershipTierEnum.BRONZE;
57	    }
58	
59	    /** Formats the owner's stored names as 'LastName, FirstName'. */
60	    default String displayName(Owner owner) {
61	        if (owner == null) {
62	            return null;
63	        }
64	        return owner.getLastName() + ", " + owner.getFirstName();
65	    }
66	
67	    /**
68	     * The owner's initials as the upper-cased first letters of the first and last
69	     * names, dot-separated with a trailing dot, e.g. 'J.S.'.
70	     */
71	    default String initials(Owner owner) {
72	        if (owner == null) {
73	            return null;
74	        }
75	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
76	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
77	    }
78	
79	    Owner toOwner(OwnerDto ownerDto);
80	
81	    @Mapping(target = "id", ignore = true)
82	    @Mapping(target = "pets", ignore = true)
83	    @Mapping(target = "customerCode", ignore = true)
84	    @Mapping(target = "membershipNumber", ignore = true)
85	    @Mapping(target = "householdId", ignore = true)
86	    @Mapping(target = "namesakeCount", ignore = true)
87	    Owner toOwner(OwnerFieldsDto ownerDto);
88	
89	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
90	
91	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
92	
93	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
94	        OwnerPageDto ownerPageDto = new OwnerPageDto();
95	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
96	        ownerPageDto.setPage(ownerPage.getNumber());
97	        ownerPageDto.setSize(ownerPage.getSize());
98	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
99	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
100	        return ownerPageDto;
101	    }
102	}
