3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.ArrayList;
7	import java.util.List;
8	import java.util.Locale;
9	
10	import net.officefloor.plugin.variable.Val;
11	import org.springframework.samples.petclinic.model.Owner;
12	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
13	import org.springframework.samples.petclinic.repository.OwnerRepository;
14	
15	/**
16	 * When the request opts in with {@code sharesHousehold} true, gives the new owner a stable
17	 * {@code householdId} shared with the existing owner(s) at the same household — same last name and
18	 * same address, compared case-insensitively with collapsed whitespace, matching
19	 * {@link EnsureOwnerHouseholdUnique}.
20	 *
21	 * <p>The identifier is deterministic (a hex prefix of SHA-256 over the normalized last name and
22	 * address), so every member of a household derives the same value and it stays stable as new members
23	 * join. Any pre-existing household member that has no identifier yet is back-filled with the same
24	 * value so the whole household shares it. Runs after {@link BuildOwner} (so the entity exists) and
25	 * before {@link SaveOwner}, mutating the not-yet-persisted owner in place.
26	 */
27	public class AssignHouseholdId {
28	
29	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
30	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
31	            return;
32	        }
33	        String lastName = normalize(owner.getLastName());
34	        String address = AddressNormalizer.normalize(owner.getAddress());
35	
36	        List<Owner> household = new ArrayList<>();
37	        String existingId = null;
38	        for (Owner existing : ownerRepository.findAll()) {
39	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
40	                continue;
41	            }
42	            if (lastName.equals(normalize(existing.getLastName()))
43	                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
44	                household.add(existing);
45	                if (existingId == null && existing.getHouseholdId() != null
46	                        && !existing.getHouseholdId().isBlank()) {
47	                    existingId = existing.getHouseholdId();
48	                }
49	            }
50	        }
51	
52	        String householdId = existingId != null ? existingId : stableId(lastName, address);
53	        owner.setHouseholdId(householdId);
54	        for (Owner member : household) {
55	            if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
56	                member.setHouseholdId(householdId);
57	                ownerRepository.save(member);
58	            }
59	        }
60	    }
61	
62	    /** Trim, collapse internal whitespace to a single space and lower-case for comparison. */
63	    private static String normalize(String value) {
64	        if (value == null) {
65	            return "";
66	        }
67	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
68	    }
69	
70	    /** First 12 upper-case hex characters of SHA-256 over the normalized last name and address. */
71	    private static String stableId(String lastName, String address) {
72	        try {
73	            byte[] digest = MessageDigest.getInstance("SHA-256")
74	                    .digest((lastName + "|" + address).getBytes(StandardCharsets.UTF_8));
75	            StringBuilder sb = new StringBuilder(digest.length * 2);
76	            for (byte b : digest) {
77	                sb.append(String.format("%02x", b));
78	            }
79	            return sb.substring(0, 12).toUpperCase(Locale.ROOT);
80	        }
81	        catch (NoSuchAlgorithmException ex) {
82	            throw new IllegalStateException("SHA-256 not available", ex);
83	        }
84	    }
85	}
