6	/**
7	 * Normalizes the owner address when creating an owner and writes the canonical form back onto the
8	 * request, so that {@link BuildOwner} persists — and the response returns — the normalized value.
9	 * Normalization is defined by {@link AddressNormalizer}: trim, collapse whitespace, upper-case and
10	 * expand common street-type abbreviations.
11	 *
12	 * <p>Runs after {@link ValidateOwner} has rejected a blank (after normalization) address, so the
13	 * value here is always non-blank; the downstream household checks then compare the normalized form.
14	 */
15	public class NormalizeOwnerAddress {
16	
17	    public void service(@Val OwnerFieldsDto request) {
18	        request.setAddress(AddressNormalizer.normalize(request.getAddress()));
19	    }
20	}
