1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Records the new owner's {@code namesakeCount}: the number of existing owners that, at the moment
9	 * this owner is created, already share the same first name and last name, compared
10	 * case-insensitively. The value is a snapshot taken before the new row is saved, so the new owner is
11	 * never counted against itself and the stored figure stays stable as later owners are added.
12	 *
13	 * <p>Runs after {@link BuildOwner} (so the entity and its names exist) and before {@link SaveOwner},
14	 * mutating the not-yet-persisted owner in place.
15	 */
16	public class AssignNamesakeCount {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
19	        String firstName = owner.getFirstName();
20	        String lastName = owner.getLastName();
21	        int count = 0;
22	        for (Owner existing : ownerRepository.findAll()) {
23	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
24	                continue;
25	            }
26	            if (equalsIgnoreCase(firstName, existing.getFirstName())
27	                    && equalsIgnoreCase(lastName, existing.getLastName())) {
28	                count++;
29	            }
30	        }
31	        owner.setNamesakeCount(count);
32	    }
33	
34	    private static boolean equalsIgnoreCase(String a, String b) {
35	        return a == null ? b == null : a.equalsIgnoreCase(b);
36	    }
37	}
