6	/**
7	 * Assigns the owner's {@code membershipNumber}, formatted {@code '<customerCode>-M<YY>'} where
8	 * YY is the last two digits of the {@code registrationDate} year (e.g. 'SYD-SMI-0007-M26').
9	 *
10	 * <p>Runs after {@link AssignCustomerCode} (so the customer code exists) and {@link BuildOwner}
11	 * (so the registration date is set), and before {@link SaveOwner}, mutating the not-yet-persisted
12	 * owner in place.
13	 */
14	public class AssignMembershipNumber {
15	
16	    public void service(@Val Owner owner) {
17	        int yy = owner.getRegistrationDate().getYear() % 100;
18	        owner.setMembershipNumber(String.format("%s-M%02d", owner.getCustomerCode(), yy));
19	    }
20	}
